// Single-file bundle of supabase/functions/payment-webhook (generated by npm run bundle:functions). Paste into the dashboard editor.

import { createClient } from "npm:@supabase/supabase-js@2";
import { createHash } from "node:crypto";
import "node:buffer";

// supabase/functions/_shared/gateways.ts
/** Compare money in paisa to avoid float noise. */
const paisa = (v) => Math.round(Number(v) * 100);
const sameAmount = (a, b) => Number.isFinite(Number(a)) && Number.isFinite(Number(b)) && paisa(a) === paisa(b);
const md5 = (s) => createHash("md5").update(s).digest("hex");
const asObj = (v) => v && typeof v === "object" ? v : {};
const sslBase = (mode) => mode === "live" ? "https://securepay.sslcommerz.com" : "https://sandbox.sslcommerz.com";
/** Verifies the callback's verify_sign (md5 over the verify_key fields + md5(store password)). */
function sslVerifySign(p, storePasswd) {
	if (!p.verify_sign || !p.verify_key) return false;
	const pairs = {};
	for (const k of p.verify_key.split(",")) if (k in p) pairs[k] = p[k];
	pairs.store_passwd = md5(storePasswd);
	const str = Object.keys(pairs).sort().map((k) => `${k}=${pairs[k]}`).join("&");
	return md5(str) === p.verify_sign;
}
async function sslValidate(f, c, valId) {
	const u = `${sslBase(c.mode)}/validator/api/validationserverAPI.php?val_id=${encodeURIComponent(valId)}&store_id=${encodeURIComponent(c.storeId)}&store_passwd=${encodeURIComponent(c.storePasswd)}&format=json`;
	return asObj(await (await f(u)).json());
}
function sslCheck(v, txn) {
	if (v.status !== "VALID" && v.status !== "VALIDATED") return {
		ok: false,
		reason: `status ${String(v.status)}`
	};
	if (v.tran_id !== txn.id) return {
		ok: false,
		reason: "transaction id mismatch"
	};
	if (v.currency_type !== "BDT") return {
		ok: false,
		reason: "currency mismatch"
	};
	if (!sameAmount(String(v.amount), txn.amount)) return {
		ok: false,
		reason: "amount mismatch"
	};
	return {
		ok: true,
		providerTxnId: String(v.bank_tran_id || v.val_id || v.tran_id)
	};
}
const bkashBase = (mode) => mode === "live" ? "https://tokenized.pay.bka.sh/v1.2.0-beta" : "https://tokenized.sandbox.bka.sh/v1.2.0-beta";
async function bkashToken(f, c) {
	const r = asObj(await (await f(`${bkashBase(c.mode)}/tokenized/checkout/token/grant`, {
		method: "POST",
		headers: {
			"Content-Type": "application/json",
			Accept: "application/json",
			username: c.username,
			password: c.password
		},
		body: JSON.stringify({
			app_key: c.appKey,
			app_secret: c.appSecret
		})
	})).json());
	if (typeof r.id_token !== "string") throw new Error(`bKash: ${String(r.statusMessage ?? "token grant failed")}`);
	return r.id_token;
}
const bkashHeaders = (c, token) => ({
	"Content-Type": "application/json",
	Accept: "application/json",
	Authorization: token,
	"X-APP-Key": c.appKey
});
/** Executes (or, if already executed, queries) the payment: this server-to-server call is the verification. */
async function bkashConfirm(f, c, paymentId, txn) {
	const token = await bkashToken(f, c);
	const call = async (path) => asObj(await (await f(`${bkashBase(c.mode)}/tokenized/checkout/${path}`, {
		method: "POST",
		headers: bkashHeaders(c, token),
		body: JSON.stringify({ paymentID: paymentId })
	})).json());
	let r = await call("execute");
	if (r.transactionStatus !== "Completed") r = await call("payment/status");
	if (r.transactionStatus !== "Completed") return {
		ok: false,
		reason: `status ${String(r.transactionStatus ?? r.statusMessage ?? "unknown")}`,
		raw: r
	};
	if (r.merchantInvoiceNumber !== txn.id) return {
		ok: false,
		reason: "invoice number mismatch",
		raw: r
	};
	if (r.currency && r.currency !== "BDT") return {
		ok: false,
		reason: "currency mismatch",
		raw: r
	};
	if (!sameAmount(String(r.amount), txn.amount)) return {
		ok: false,
		reason: "amount mismatch",
		raw: r
	};
	return {
		ok: true,
		providerTxnId: String(r.trxID),
		raw: r
	};
}
const nagadBase = (mode) => mode === "live" ? "https://api.mynagad.com/api/dfs" : "http://sandbox.mynagad.com:10080/remote-payment-gateway-1.0/api/dfs";
/** Nagad order ids are short alphanumerics: derive one from the transaction uuid (and re-derive to verify). */
const nagadOrderId = (txnId) => `N${txnId.replace(/-/g, "").slice(0, 19)}`;
const nagadHeaders = (ip) => ({
	"Content-Type": "application/json",
	"X-KM-IP-V4": ip,
	"X-KM-Client-Type": "PC_WEB",
	"X-KM-Api-Version": "v-0.2.0"
});
async function nagadConfirm(f, c, paymentRefId, txn) {
	const r = asObj(await (await f(`${nagadBase(c.mode)}/verify/payment/${encodeURIComponent(paymentRefId)}`, { headers: nagadHeaders("127.0.0.1") })).json());
	if (r.status !== "Success") return {
		ok: false,
		reason: `status ${String(r.status ?? r.message ?? "unknown")}`,
		raw: r
	};
	if (r.orderId !== nagadOrderId(txn.id)) return {
		ok: false,
		reason: "order id mismatch",
		raw: r
	};
	if (!sameAmount(String(r.amount), txn.amount)) return {
		ok: false,
		reason: "amount mismatch",
		raw: r
	};
	return {
		ok: true,
		providerTxnId: String(r.issuerPaymentRefNo || r.paymentRefId || paymentRefId),
		raw: r
	};
}
const SECRET_NAMES = {
	sslcommerz: ["SSLCOMMERZ_STORE_ID", "SSLCOMMERZ_STORE_PASSWORD"],
	bkash: [
		"BKASH_APP_KEY",
		"BKASH_APP_SECRET",
		"BKASH_USERNAME",
		"BKASH_PASSWORD"
	],
	nagad: [
		"NAGAD_MERCHANT_ID",
		"NAGAD_MERCHANT_PRIVATE_KEY",
		"NAGAD_PG_PUBLIC_KEY"
	]
};
/** Returns the provider's config, or null when any required secret is missing (provider then counts as "not configured"). */
function loadConfig(provider, get, mode) {
	const v = Object.fromEntries(SECRET_NAMES[provider].map((n) => [n, get(n)?.trim()]));
	if (Object.values(v).some((x) => !x)) return null;
	if (provider === "sslcommerz") return {
		storeId: v.SSLCOMMERZ_STORE_ID,
		storePasswd: v.SSLCOMMERZ_STORE_PASSWORD,
		mode
	};
	if (provider === "bkash") return {
		appKey: v.BKASH_APP_KEY,
		appSecret: v.BKASH_APP_SECRET,
		username: v.BKASH_USERNAME,
		password: v.BKASH_PASSWORD,
		mode
	};
	return {
		merchantId: v.NAGAD_MERCHANT_ID,
		privateKey: v.NAGAD_MERCHANT_PRIVATE_KEY,
		pgPublicKey: v.NAGAD_PG_PUBLIC_KEY,
		mode
	};
}

// supabase/functions/payment-webhook/index.ts
const f = (url, init) => fetch(url, init);
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const PROVIDERS = [
	"sslcommerz",
	"bkash",
	"nagad"
];
Deno.serve(async (req) => {
	const u = new URL(req.url);
	const provider = u.searchParams.get("provider");
	const txnId = u.searchParams.get("txn") ?? "";
	const result = u.searchParams.get("result") ?? "";
	const site = (Deno.env.get("SITE_URL") ?? "").replace(/\/$/, "");
	const isIpn = result === "ipn";
	const finish = (status, code = 200) => isIpn || !site ? new Response(JSON.stringify({ status }), {
		status: code,
		headers: { "Content-Type": "application/json" }
	}) : new Response(null, {
		status: 303,
		headers: { Location: `${site}/customer/pay?status=${status}` }
	});
	if (!PROVIDERS.includes(provider) || !UUID.test(txnId)) return new Response(JSON.stringify({ error: "bad_request" }), { status: 400 });
	const admin = createClient(Deno.env.get("SUPABASE_URL"), Deno.env.get("SUPABASE_SERVICE_ROLE_KEY"), { auth: { persistSession: false } });
	const params = {};
	for (const [k, v] of u.searchParams) params[k] = v;
	if (req.method === "POST") {
		const ct = req.headers.get("content-type") ?? "";
		try {
			if (ct.includes("application/json")) for (const [k, v] of Object.entries(await req.json())) params[k] = String(v);
			else for (const [k, v] of new URLSearchParams(await req.text())) params[k] = v;
		} catch {}
	}
	const { data: txn } = await admin.from("payment_gateway_transactions").select("id, provider, amount, status, mode, request_payload").eq("id", txnId).maybeSingle();
	if (!txn || txn.provider !== provider) return new Response(JSON.stringify({ error: "unknown_transaction" }), { status: 404 });
	if (txn.status === "verified") return finish("success");
	const mode = txn.mode;
	const cfg = loadConfig(provider, (n) => Deno.env.get(n), mode);
	if (!cfg) return finish("error", 500);
	const t = {
		id: txn.id,
		amount: Number(txn.amount)
	};
	const ref = txn.request_payload?.provider_ref;
	const note = (reason) => admin.from("payment_gateway_transactions").update({ response_payload: {
		ignored: reason,
		at: (/* @__PURE__ */ new Date()).toISOString()
	} }).eq("id", t.id).neq("status", "verified");
	try {
		let providerTxnId = null;
		let raw = {};
		if (provider === "sslcommerz") {
			if (result === "fail") return finish("failed");
			if (result === "cancel") return finish("cancelled");
			if (!sslVerifySign(params, cfg.storePasswd)) {
				await note("invalid verify_sign");
				return finish("error", 400);
			}
			const v = await sslValidate(f, cfg, params.val_id ?? "");
			const c = sslCheck(v, t);
			if (!c.ok) {
				await note(c.reason);
				return finish("failed");
			}
			providerTxnId = c.providerTxnId;
			raw = v;
		} else if (provider === "bkash") {
			const paymentId = params.paymentID ?? "";
			if (!paymentId || paymentId !== ref) {
				await note("payment id does not belong to this transaction");
				return finish("error", 400);
			}
			if (params.status && params.status !== "success") return finish(params.status === "cancel" ? "cancelled" : "failed");
			const c = await bkashConfirm(f, cfg, paymentId, t);
			if (!c.ok) {
				await note(c.reason);
				return finish("failed");
			}
			providerTxnId = c.providerTxnId;
			raw = c.raw;
		} else {
			const refId = params.payment_ref_id ?? "";
			if (!refId || refId !== ref) {
				await note("payment ref does not belong to this transaction");
				return finish("error", 400);
			}
			if (params.status && params.status !== "Success") return finish(params.status === "Aborted" ? "cancelled" : "failed");
			const c = await nagadConfirm(f, cfg, refId, t);
			if (!c.ok) {
				await note(c.reason);
				return finish("failed");
			}
			providerTxnId = c.providerTxnId;
			raw = c.raw;
		}
		const { error } = await admin.rpc("finalize_gateway_payment", {
			p_txn: t.id,
			p_provider_txn_id: providerTxnId,
			p_response: raw,
			p_signature_valid: true
		});
		if (error) {
			await note(`finalize failed: ${error.message}`);
			return finish("error", 500);
		}
		return finish("success");
	} catch (e) {
		await note(`error: ${e.message}`);
		return finish("error", 502);
	}
});
